REPLACE INTO `tanaman` VALUES (3,'Aglaonema','Aglaonema spp.','Tanaman Hias','Daun berwarna cantik untuk dalam ruangan.','Tanaman hias dengan daun hijau, merah, atau bercorak. Bentuknya kompak dan tahan di tempat kurang cahaya.','Sebagai penghias dalam ruangan dan membantu menyegarkan udara.','Suka tempat teduh atau cahaya tidak langsung. Disiram setelah media agak kering dan jangan sampai tergenang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (4,'Kitolod','Hippobroma longiflora','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman kecil yang tumbuh rendah, tingginya sekitar 20–30 cm. Daunnya bergerigi dan bunganya putih berbentuk bintang. Getahnya beracun jika tertelan.','Secara tradisional digunakan untuk meredakan mata yang sakit, batuk, dan sesak napas. Sebaiknya hanya untuk pemakaian luar atau dengan arahan ahli, karena mengandung zat yang berbahaya jika berlebihan.','Suka tempat terang sampai agak teduh dengan tanah yang gembur dan lembap. Disiram 2–3 kali seminggu. Mudah tumbuh sendiri dan dapat ditanam dari biji.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (5,'Daun saga','Abrus precatorius','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman merambat dengan daun kecil-kecil. Buahnya berupa polong berisi biji merah-hitam yang sangat beracun.','Daunnya secara tradisional direbus atau dikunyah untuk meredakan sariawan, sakit tenggorokan, dan batuk. Bijinya tidak boleh dikonsumsi karena beracun.','Perlu sinar matahari penuh dan tanah yang tidak menggenang. Disiram secukupnya dan diberi tiang untuk merambat. Jauhkan bijinya dari anak-anak.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (6,'Daun kelor','Moringa oleifera','Tanaman Obat','Kelompok: Tanaman Obat.','Pohon berukuran sedang dengan daun kecil berwarna hijau, bunga putih kekuningan, dan buah berbentuk polong panjang.','Kaya protein, vitamin, kalsium, dan zat besi. Membantu menjaga daya tahan tubuh, melancarkan ASI, dan menjaga kadar gula darah.','Perlu sinar matahari penuh dan tanah yang tidak tergenang. Tahan kekeringan. Dapat ditanam dari potongan batang atau biji, dan sebaiknya dipangkas agar mudah dipetik.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (7,'Cocor bebek','Kalanchoe pinnata','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman berdaun tebal dan berair dengan tepi bergerigi. Tunas baru tumbuh dari tepi daunnya.','Daunnya secara tradisional ditempelkan atau diremas untuk meredakan bisul, luka ringan, demam, dan sakit kepala.','Suka tempat terang dengan tanah berpasir yang cepat kering. Cukup disiram sedikit, sekitar seminggu sekali. Mudah tumbuh dari daun yang jatuh.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (8,'Kunyit kuning','Curcuma longa','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman setinggi sekitar 1 m dengan daun lebar. Umbi akarnya berwarna kuning-oranye dan berbau khas.','Membantu melancarkan pencernaan, meredakan nyeri haid, dan menjaga kesehatan hati. Juga digunakan sebagai bumbu dan pewarna makanan alami.','Cocok di tempat setengah teduh dengan tanah gembur yang subur. Disiram teratur tanpa menggenang. Dapat dipanen sekitar umur 8–10 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (9,'Kunyit putih','Curcuma zedoaria','Tanaman Obat','Kelompok: Tanaman Obat.','Umbi akarnya berwarna putih kekuningan dengan aroma seperti mangga mentah. Daunnya lebar dengan garis ungu di tengah.','Secara tradisional digunakan untuk meredakan perut kembung dan gangguan pencernaan serta menjaga stamina. Ibu hamil sebaiknya berkonsultasi dahulu.','Suka tempat agak teduh dengan tanah subur, gembur, dan lembap. Ditanam dari potongan umbi yang sudah bertunas.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (10,'Bangun-bangun','Plectranthus amboinicus','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman berbatang lunak dengan daun tebal berbulu halus, berbau tajam, dan tepi daun bergerigi.','Dikenal dapat melancarkan ASI serta meredakan batuk, pilek, demam, dan masuk angin. Sering dimasak sebagai sayur bening atau pepes.','Suka tempat terang sampai agak teduh dengan tanah gembur. Disiram 2 kali seminggu. Mudah ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (11,'Bawang dayak','Eleutherine bulbosa','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman berdaun panjang seperti pedang dengan umbi merah tua mirip bawang merah kecil dan bunga putih.','Umbinya diolah menjadi teh atau ramuan untuk membantu menjaga kadar kolesterol dan gula darah serta melawan kuman.','Suka tempat agak teduh dengan tanah gembur dan lembap. Ditanam dari umbi atau anakan. Umbi dapat dipanen pada umur 3–4 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (12,'Patah tulang','Euphorbia tirucalli','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman perdu dengan cabang ramping seperti pensil hijau dan hampir tanpa daun. Getahnya putih dan sangat perih jika terkena kulit atau mata.','Secara tradisional dibalurkan pada bagian luar tubuh untuk membantu pemulihan keseleo dan nyeri sendi. Tidak boleh diminum karena getahnya beracun.','Perlu sinar matahari penuh dan tanah berpasir. Hampir tidak perlu disiram. Gunakan sarung tangan saat memangkas karena getahnya berbahaya.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (13,'Daun sirih / sirih hijau','Piper betle','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman merambat dengan daun hijau berbentuk jantung. Rasa dan aromanya khas dan agak tajam.','Air rebusannya digunakan untuk mengatasi bau mulut, keputihan, mimisan, gatal, dan mata merah. Juga dapat membersihkan luka ringan.','Suka tempat agak teduh dengan tanah lembap dan subur. Perlu tiang untuk merambat dan disiram teratur.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (14,'Kencur','Kaempferia galanga','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman pendek dengan daun lebar yang menempel di tanah. Umbi akarnya berwarna cokelat muda dan harum.','Digunakan dalam jamu beras kencur untuk meredakan batuk dan perut kembung, menambah nafsu makan, serta mengurangi pegal-pegal.','Suka tempat agak teduh dengan tanah gembur dan lembap. Dapat ditanam di polybag dan dipanen pada umur 6–8 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (15,'Bangle','Zingiber purpureum','Tanaman Obat','Kelompok: Tanaman Obat.','Umbi akarnya besar, berwarna kuning pucat, berbau tajam, dan rasanya pahit-pedas. Daunnya panjang dan runcing.','Secara tradisional digunakan untuk membantu menurunkan berat badan, melancarkan buang air besar, dan meredakan nyeri sendi. Tidak dianjurkan bagi ibu hamil.','Cocok di tempat agak teduh sampai terang dengan tanah subur dan gembur. Disiram teratur. Dapat dipanen sekitar umur 9–12 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (16,'Sereh','Cymbopogon citratus','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman berumpun seperti rumput, tingginya 1–1,5 m. Batangnya berbau segar seperti lemon.','Meredakan masuk angin dan perut kembung, penyedap masakan dan minuman hangat, serta dapat mengusir nyamuk.','Perlu sinar matahari penuh dan tanah yang tidak tergenang. Dapat diperbanyak dengan memisahkan rumpunnya.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (17,'Lidah buaya','Aloe vera','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman berdaun tebal berdaging yang tersusun melingkar. Di dalam daunnya terdapat gel bening, dan tepinya sedikit berduri.','Gelnya digunakan untuk merawat luka bakar ringan, kulit, dan rambut, serta dapat dibuat minuman. Getah kuning di kulit daun dapat memicu mencret, jadi hindari berlebihan.','Suka tempat terang sampai terkena matahari penuh. Gunakan tanah berpasir dan siram setelah tanah kering, sekitar 1–2 minggu sekali.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (18,'Kumis kucing','Orthosiphon aristatus','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman tegak berdaun oval bergerigi dengan bunga ungu atau putih. Benang sarinya panjang seperti kumis kucing.','Teh daunnya membantu memperlancar buang air kecil. Secara tradisional digunakan untuk batu ginjal, infeksi saluran kemih, dan tekanan darah tinggi.','Suka tempat cukup terang sampai agak teduh dengan tanah gembur dan lembap. Mudah ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (19,'Binahong','Anredera cordifolia','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman merambat dengan daun tebal berbentuk jantung dan bunga kecil putih yang harum. Umbi kecil tumbuh di sela daunnya.','Daunnya dikenal dapat mempercepat penyembuhan luka, membantu mengatasi maag dan diabetes, serta menjaga stamina. Dapat dimakan sebagai lalapan atau direbus.','Cocok di tempat cukup terang sampai agak teduh dengan tanah gembur. Disiram teratur dan diberi tiang untuk merambat.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (20,'Tanaman jahe','Zingiber officinale','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman tegak setinggi 60–100 cm dengan daun sempit. Umbi akarnya berwarna krem, rasanya pedas dan menghangatkan.','Menghangatkan badan, meredakan mual dan masuk angin, mengurangi nyeri otot, serta melancarkan pencernaan. Digunakan sebagai bumbu dan wedang.','Suka tempat agak teduh dengan tanah subur dan gembur. Disiram teratur tanpa menggenang. Dapat dipanen pada umur 8–10 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (21,'Dandang gendis','Clinacanthus nutans','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman perdu dengan daun sempit berwarna hijau tua mengilap dan batang ramping yang menjuntai.','Daunnya secara tradisional diseduh atau ditempelkan pada kulit untuk membantu meredakan radang, herpes, luka bakar, dan diabetes.','Suka tempat terang sampai agak teduh dengan tanah gembur dan lembap. Mudah ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (22,'Temulawak','Curcuma zanthorrhiza','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman tegak setinggi 1–2 m. Umbi akarnya berwarna kuning jingga, rasanya pahit, dan daunnya lebar dengan garis ungu.','Dikenal dapat menjaga kesehatan hati, menambah nafsu makan, dan melancarkan pencernaan. Banyak digunakan sebagai bahan jamu.','Suka tempat agak teduh dengan tanah gembur yang banyak bahan organik. Disiram teratur. Dapat dipanen pada umur 9–12 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (23,'Pegagan','Centella asiatica','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman yang menjalar di tanah dengan daun bulat berlekuk berwarna hijau segar.','Membantu menyembuhkan luka, melancarkan peredaran darah, menjaga daya ingat, dan menenangkan. Dapat dimakan sebagai lalapan atau diseduh menjadi teh.','Suka tempat agak teduh dengan tanah lembap dan tidak tahan kering. Mudah ditanam dari sulur yang menjalar.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (24,'Kemangi','Ocimum × africanum','Tanaman Obat','Kelompok: Tanaman Obat.','Tanaman kecil setinggi 30–60 cm dengan daun hijau muda yang wangi dan bunga putih kecil.','Digunakan sebagai lalapan dan pelengkap masakan. Membantu pencernaan, mengurangi perut kembung dan bau mulut, serta melancarkan ASI.','Perlu sinar matahari penuh dan tanah gembur yang lembap. Bunganya dipangkas agar daun terus tumbuh. Ditanam dari biji.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (25,'Kenanga','Cananga odorata','Tanaman Hias','Kelompok: Tanaman Hias.','Pohon tinggi dengan daun lonjong. Bunganya berwarna kuning kehijauan, berbentuk bintang, dan sangat harum.','Bunganya digunakan untuk hiasan dan upacara adat, bahan minyak wangi, serta aromaterapi.','Perlu sinar matahari penuh dan tanah subur yang lembap. Disiram rutin dan dipangkas agar tidak terlalu tinggi.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (26,'Daun pandan / pohon pandan','Pandanus amaryllifolius','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu berumpun dengan daun panjang dan pipih berwarna hijau yang harum.','Digunakan sebagai pewangi dan pewarna alami makanan, serta pengharum ruangan.','Suka tempat agak teduh dengan tanah gembur dan lembap. Disiram 2–3 kali seminggu. Dapat diperbanyak dengan anakannya.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (27,'Daun suji','Dracaena angustifolia','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu berumpun dengan daun hijau tua yang panjang dan melengkung.','Sebagai tanaman hias taman, dan daunnya digunakan sebagai pewarna hijau alami serta pewangi kue tradisional.','Suka tempat teduh sampai agak teduh dengan tanah gembur dan lembap. Dapat ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (28,'Melati','Jasminum sambac','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu kecil dengan daun hijau mengilap. Bunganya putih kecil dan sangat harum.','Sebagai tanaman hias yang harum. Bunganya digunakan untuk teh, minyak wangi, dan rangkaian upacara adat. Melati juga dikenal sebagai bunga nasional Indonesia.','Perlu sinar matahari penuh dan tanah subur yang gembur. Disiram rutin dan dipangkas agar banyak berbunga.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (29,'Bakung','Crinum asiaticum','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman berumbi besar dengan daun lebar seperti pita. Bunganya putih, berumbai, dan harum pada malam hari.','Sebagai tanaman hias taman. Daunnya secara tradisional digunakan untuk pemakaian luar pada bengkak dan nyeri sendi. Umbinya beracun jika dimakan.','Cocok di tempat setengah teduh sampai terang dengan tanah yang lembap. Tumbuh baik di tepi kolam. Ditanam dari anakan umbi.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (30,'Bambu Jepang','Pseudosasa japonica','Tanaman Hias','Kelompok: Tanaman Hias.','Bambu kecil yang bercabang dengan batang hijau dan daun sempit memanjang yang tumbuh rapat.','Digunakan sebagai pagar hidup dan peneduh taman, serta mempercantik tampilan taman minimalis.','Cocok di tempat terang sampai agak teduh dengan tanah gembur dan subur. Disiram sekitar 3 kali seminggu. Tahan angin.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (31,'Syngonium wendlandii','Syngonium wendlandii','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman merambat dengan daun berbentuk anak panah berwarna hijau gelap dengan garis putih keperakan.','Sebagai tanaman hias dalam ruangan, cocok untuk pot gantung atau dirambatkan pada tiang.','Suka cahaya terang yang tidak langsung dan media yang gembur dan lembap. Disiram saat permukaan media mulai kering.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (32,'Kembang sepatu','Hibiscus rosa-sinensis','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu setinggi 1–3 m dengan bunga besar berwarna merah, jingga, kuning, atau merah muda berbentuk terompet.','Sebagai tanaman hias taman. Bunganya secara tradisional digunakan untuk meredakan demam dan batuk, serta dapat diseduh menjadi teh.','Perlu sinar matahari penuh dan tanah subur. Disiram sehari sekali saat cuaca panas, serta dipangkas dan dipupuk secara berkala.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (33,'Keladi','Caladium bicolor','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman berumbi dengan daun lebar berbentuk hati yang bercorak merah muda, putih, dan hijau.','Sebagai tanaman hias daun. Seluruh bagiannya dapat membuat gatal dan perih, sehingga jangan dimakan.','Suka tempat agak teduh dengan tanah gembur dan lembap. Daunnya rontok saat musim kering, lalu tumbuh lagi dari umbinya.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (34,'Kayu urip','Gliricidia sepium','Tanaman Hias','Kelompok: Tanaman Hias.','Pohon kecil yang bercabang dengan daun majemuk dan bunga merah muda keunguan. Sering digunakan sebagai pagar hidup.','Digunakan sebagai pagar hidup, peneduh, pupuk hijau penyubur tanah, dan pakan ternak. Nama ini dapat berbeda di tiap daerah.','Perlu sinar matahari penuh dan tahan kering. Dapat tumbuh di berbagai jenis tanah dan mudah ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (35,'Pucuk merah','Syzygium oleana','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu padat dengan pucuk daun muda berwarna merah mengilap, sedangkan daun tuanya hijau tua.','Sebagai pagar hidup dan penghias taman, serta membantu menyerap debu.','Perlu sinar matahari penuh dan tanah gembur. Disiram teratur dan dipangkas agar berbentuk pagar atau bulat.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (36,'Mangkokan','Polyscias scutellaria','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu dengan daun bulat dan tebal seperti mangkuk, berwarna hijau mengilap atau belang putih.','Sebagai tanaman pagar dan hias. Daunnya secara tradisional digunakan untuk melancarkan ASI dan meredakan demam ringan.','Suka tempat terang sampai agak teduh dengan tanah gembur dan lembap. Mudah ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (37,'Bunga Asoka','Ixora coccinea','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu dengan bunga bergerombol berwarna merah, jingga, atau kuning, serta daun hijau tua yang mengilap.','Sebagai tanaman hias dan pagar. Bunga dan akarnya secara tradisional digunakan untuk membantu menurunkan tekanan darah dan mengatasi diare ringan.','Perlu sinar matahari penuh dan tanah subur. Disiram rutin dan dipangkas setelah berbunga agar tumbuh rimbun.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (38,'Kuping gajah','Anthurium crystallinum','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman berdaun besar berbentuk hati seperti telinga gajah, dengan garis putih keperakan yang jelas.','Sebagai tanaman hias dalam ruangan yang menarik dan membuat ruangan terasa lebih segar.','Suka cahaya terang yang tidak langsung dan udara lembap. Hindari sinar matahari langsung. Gunakan media yang gembur dan lembap.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (39,'Wali Songo','Schefflera arboricola','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu dengan daun menjari berjumlah 7–9 helai, berwarna hijau mengilap, dan tumbuh rimbun.','Sebagai tanaman hias pot dan pagar. Tahan di tempat teduh dan membantu menyegarkan udara.','Suka tempat terang sampai agak teduh dengan tanah gembur. Disiram 2 kali seminggu. Mudah ditanam dari potongan batang.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (40,'Ketapang kencana','Terminalia mantaly','Tanaman Hias','Kelompok: Tanaman Hias.','Pohon berbentuk payung bertingkat dengan daun bulat yang mengelompok di ujung cabang.','Sebagai pohon peneduh di jalan, taman, dan halaman. Bentuk tajuknya yang bertingkat sangat menarik.','Perlu sinar matahari penuh dan tanah yang tidak tergenang. Disiram secara rutin saat masih muda dan dipangkas untuk membentuk tajuk.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (41,'Patah tulang daun keriting','Pedilanthus tithymaloides','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu dengan batang berbelok-belok dan daun hijau yang bergelombang. Getahnya putih dan dapat membuat kulit perih.','Sebagai tanaman hias pot yang unik. Getahnya beracun, sehingga harus dijauhkan dari anak-anak dan hewan peliharaan.','Cocok di tempat terang sampai setengah teduh dengan tanah berpasir. Cukup disiram sedikit. Gunakan sarung tangan saat memangkas.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (42,'Bunga Kasandra','Lantana camara','Tanaman Hias','Kelompok: Tanaman Hias.','Tanaman perdu dengan bunga bergerombol warna-warni, seperti merah, jingga, kuning, dan ungu, yang berubah warna seiring waktu.','Sebagai tanaman hias yang menarik kupu-kupu dan lebah. Daun dan buahnya beracun jika dimakan.','Perlu sinar matahari penuh dan tahan kering. Dapat tumbuh di berbagai jenis tanah. Dipangkas rutin agar banyak berbunga.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (43,'Pepaya','Carica papaya','Tanaman Pangan / Sayuran / Buah','Kelompok: Tanaman Pangan / Sayuran / Buah.','Pohon dengan batang tunggal yang tidak berkayu dan daun besar menjari. Buahnya berdaging oranye atau merah.','Buahnya kaya vitamin A dan C serta membantu pencernaan dan melancarkan buang air besar. Daun dan bunganya dapat dimasak sebagai sayur.','Perlu sinar matahari penuh dan tanah subur yang gembur. Disiram teratur tanpa menggenang dan dipupuk organik tiap 2–3 bulan. Mulai berbuah pada umur 8–12 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (44,'Cabe rawit','Capsicum frutescens','Tanaman Pangan / Sayuran / Buah','Kelompok: Tanaman Pangan / Sayuran / Buah.','Tanaman perdu kecil setinggi 0,5–1,5 m dengan buah kecil yang sangat pedas, hijau saat muda dan merah saat matang.','Digunakan sebagai bumbu pedas masakan. Rasa pedasnya menghangatkan badan dan menambah nafsu makan, serta kaya vitamin C.','Perlu sinar matahari penuh dan tanah gembur yang banyak bahan organik. Disiram pagi atau sore dan dipupuk berkala agar berbuah lebat.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (45,'Cabe hijau','Capsicum annuum','Tanaman Pangan / Sayuran / Buah','Kelompok: Tanaman Pangan / Sayuran / Buah.','Tanaman perdu dengan buah panjang yang berwarna hijau saat muda. Rasa pedasnya ringan sampai sedang.','Digunakan sebagai sayuran dan bumbu masakan. Sumber vitamin C dan membantu menjaga daya tahan tubuh.','Perlu sinar matahari penuh dan tanah subur yang lembap tetapi tidak tergenang. Ditanam dari biji dan dapat dipanen pada umur 3–4 bulan.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (46,'Jagung','Zea mays','Tanaman Pangan / Sayuran / Buah','Kelompok: Tanaman Pangan / Sayuran / Buah.','Tanaman setahun seperti rumput, tingginya 1,5–3 m. Tongkolnya berisi biji kuning atau putih yang terbungkus kulit.','Sumber karbohidrat dan serat, dapat menjadi makanan pokok pengganti nasi, serta bahan pakan ternak dan tepung maizena.','Perlu sinar matahari penuh, tanah subur dan gembur, serta air yang cukup. Jarak tanam sekitar 70 × 25 cm. Jagung manis dapat dipanen pada umur 70–85 hari.',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (47,'Mangga','Mangifera indica','Tanaman Pangan / Sayuran / Buah','Kelompok: Tanaman Pangan / Sayuran / Buah.','Pohon besar rindang berdaun lonjong, buah berdaging manis atau asam tergantung varietas.','Buah kaya vitamin A, C, dan serat; dimakan segar, jus, rujak, asinan; pohon juga sebagai peneduh.','Matahari penuh, tanah dalam dan drainase baik, siram saat muda. Pangkas pemeliharaan; berbuah umur 3–5 tahun (cangkok/okulasi).',NULL,NULL,'','2026-10-07 10:47:08');
REPLACE INTO `tanaman` VALUES (48,'Terong','Solanum melongena','Tanaman Pangan / Sayuran / Buah','Kelompok: Tanaman Pangan / Sayuran / Buah.','Semak tegak setinggi 60–100 cm, bunga ungu, buah memanjang atau bulat berwarna ungu/hijau/putih.','Sayuran rendah kalori kaya serat dan antosianin; membantu menjaga kolesterol dan kesehatan jantung.','Matahari penuh, tanah gembur banyak humus, siram rutin. Panen 70–90 hari setelah tanam.','8a22807719ec4ec4.webp',NULL,'','2026-10-07 10:47:08');
